// Event Row: the sub entry carries one item with the same keys as a launch row (Client, Table,
// View, Tiers, Sources, Departments, Roles, Max companies). This is how an insert door calls this
// machine after landing: Table "Companies", View "Not Sourced". Shape it like Fetch Launch
// Record's output so Resolve Base and Launch Params read one shape on both entries; the camelCase
// spellings a door might send are folded into the row keys here. Sources is still folded so a
// door or a launch row from before the Tiers mode still resolves.
const j=$input.first().json||{};
const f=(j.fields&&typeof j.fields==='object')?Object.assign({},j.fields):Object.assign({},j);
const arr=(v)=>Array.isArray(v)?v:(v?[v]:[]);
const alias=(key,alts)=>{ if(f[key]===undefined||f[key]===''||f[key]===null){ for(const a of alts){ if(f[a]!==undefined&&f[a]!==''&&f[a]!==null){ f[key]=f[a]; break; } } } };
alias('Table',['table']); alias('View',['view']); alias('Tiers',['tiers']); alias('Sources',['sources']); alias('Departments',['departments']); alias('Roles',['roles']); alias('Max companies',['maxCompanies','max_companies']);
f.Client=arr(f.Client||f.client||f.clientRecId||f.clientRecordId).map(x=>(x&&typeof x==='object')?x.id:x).filter(Boolean);
if(!f.Client.length){ throw new Error('Waterfall Contacts was called without a Client. Pass the Hub Clients record id as Client. Nothing was pulled.'); }
return [{ json: { id: '', fields: f, _event: true } }];

// Launch Params: the launch row (or the caller's passthrough item, same keys) is the whole
// contract. Read: Client (resolves the base), Table (by name, required, no default, and it must be
// "Companies": this machine sources people for companies and refuses any other table), View (a
// Companies view, by name, required, no default; the insert doors call with "Not Sourced"), Tiers
// (the named mode, see below), Departments (mapped into each provider's own vocabulary; blank or
// ALL means no department filter), Roles (the seniority lever, see below), Max companies (the
// spend cap, required). Tag is not read: People stores no Tag, it is a lookup through the
// Companies link (ruled 2026-09-02). Any missing piece stops the run here, before a paid call.
//
// REFUSALS (2026-09-03). A launch row that was not properly filled is an EXPECTED outcome, not a
// crash, and it must be visible on the row the Operator launched. So every guard below RETURNS a
// refusal item (`refused` carries the named reason) instead of throwing. `Launch OK?` routes that
// item to Build Refusal, which closes the launch row as Failed with the reason and the execution
// link, and the run ends there: no table read, no paid call, nothing written. Only genuinely
// unexpected errors still throw, so the Error Logger keeps catching real crashes and nothing else.
// The row is already stamped Running with the Execution ID before this node runs, so the close is
// an upsert onto that same row.
//
// TIERS (Hub Automations fldMg1W5uqWocEPSe, single select, ruled 2026-09-02). One named mode
// instead of an arbitrary source set:
//   "ContaGen -> Supersoniq -> AI-Ark"  the full waterfall
//   "AI-Ark"                            the intent path: AI-Ark only, a flat cap of five people
//                                       per company and the buyer seniorities only
//   "ContaGen -> Supersoniq"            the waterfall without AI-Ark
// Blank falls back to the older Sources multi-select so launch rows in flight keep working; blank
// on both is the full waterfall. Sources is superseded and can be deleted once nothing carries it.
//
// ROLES (Hub Automations fld0NcoXexQgV4iiw, multi select, ruled 2026-09-02). The provider-neutral
// seniority vocabulary, the same one People.Seniority carries, mapped into each provider's own
// filter vocabulary. A pick OVERRIDES that provider's in-code seniority net; blank leaves every
// provider on its default, byte for byte as before. A role with no home at a provider is dropped
// there and named in the run log, exactly as Departments already behaves. The mapping:
//
//   Roles          ContaGen (DiscoLike)  Supersoniq                  AI-Ark
//   Founder        executive             Founder                     founder
//   Owner          executive             Owner                       owner
//   Partner        executive             Partner                     partner
//   Board / Chair  executive             Board / Chair               (none)
//   C-Suite        executive             C-Suite                     c_suite
//   President      executive             President                   c_suite
//   Executive      executive             C-Suite                     c_suite
//   VP             vp                    VP                          vp
//   EVP / SVP      vp                    EVP / SVP                   vp
//   Head           director              Head                        head
//   Director       director              Director                    director
//   Manager        manager               Manager, Senior Manager     manager
//   Senior         senior_ic             Senior                      (none)
//   Unclassified   (none)                Unclassified                (none)
//
// Every provider value in the three vocabularies has a home above and nothing outside them is
// ever sent. When a pick maps to nothing at a provider that provider keeps its in-code default,
// so an override never narrows a net to empty.
let rec=null, trigger='form';
try{ rec=$('Fetch Launch Record').first().json; }catch(e){}
if(!rec||!rec.fields){ rec=$('Event Row').first().json; trigger='event'; }
const f=rec.fields||{};
// Resolve Base is allowed to answer with an error item (a launch row with no Client link is asked
// for record "recMISSING"), so read it defensively: no Clayroots Base ID means the base guard
// below refuses, it never crashes here.
const cf=(($('Resolve Base').first().json||{}).fields)||{};
const base=((cf['Clayroots Base ID']||'')+'').trim();
const arr=(v)=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
const where='Launch record '+(rec.id||'(event)');
const clientRecId=(arr(f['Client']).map(x=>(x&&typeof x==='object')?x.id:x)[0])||'';
const table=((f['Table']||'')+'').trim();
const view=((f['View']||'')+'').trim();
const maxCompanies=Math.floor(Number(f['Max companies'])||0);
const tiersRaw=((f['Tiers']||'')+'').trim();
const startedAt=new Date().toISOString();
// Every refusal carries what the row actually held, so the Failed row names the reason AND shows
// the Operator the launch row as the machine read it.
const refuse=(reason)=>[{ json:{
  refused: reason,
  trigger: trigger,
  _launchRecordId: rec.id||'',
  clientRecId: clientRecId,
  base: base,
  table: table,
  view: view,
  maxCompanies: maxCompanies,
  tiers: tiersRaw,
  startedAt: startedAt
} }];
if(!clientRecId){ return refuse(where+' has no Client link. Nothing was pulled.'); }
if(!/^app[A-Za-z0-9]{14}$/.test(base)){ return refuse('Client on '+where.toLowerCase()+' has no valid Clayroots Base ID. Nothing was pulled.'); }
if(!table){ return refuse(where+' has no Table. This machine takes Table "Companies" by name, no default. Nothing was pulled.'); }
if(table.toLowerCase()!=='companies'){ return refuse(where+' names Table "'+table+'". This machine sources people for companies and takes only Table "Companies". Nothing was pulled.'); }
if(!view){ return refuse(where+' has no View. A Companies view is required by name, no default (the insert doors pass "Not Sourced"). Nothing was pulled.'); }
if(!(maxCompanies>0)){ return refuse(where+' has no Max companies. It is the spend cap and it is required. Nothing was pulled.'); }
const ALL_SOURCES=['ContaGen','Supersoniq','AI-Ark'];
const slug=(s)=>String(s).toLowerCase().replace(/[^a-z]/g,'');
const MODES=[
  { label:'ContaGen -> Supersoniq -> AI-Ark', sources:['ContaGen','Supersoniq','AI-Ark'] },
  { label:'AI-Ark', sources:['AI-Ark'] },
  { label:'ContaGen -> Supersoniq', sources:['ContaGen','Supersoniq'] }
];
const modeKey=(s)=>String(s||'').toLowerCase().replace(/[^a-z]/g,'');
let sources=null, tiers='';
if(tiersRaw){
  const hit=MODES.find(m=>modeKey(m.label)===modeKey(tiersRaw));
  if(!hit){ return refuse(where+' names Tiers "'+tiersRaw+'", which is not one of the three modes ('+MODES.map(m=>m.label).join(', ')+'). Nothing was pulled.'); }
  sources=hit.sources.slice(); tiers=hit.label;
}
if(!sources){
  const srcRaw=arr(f['Sources']).map(s=>String(s).trim()).filter(Boolean);
  const picked=ALL_SOURCES.filter(s=>srcRaw.some(x=>slug(x)===slug(s)));
  sources=picked.length?picked:ALL_SOURCES.slice();
  const hit=MODES.find(m=>m.sources.length===sources.length&&m.sources.every(s=>sources.indexOf(s)>-1));
  tiers=(hit?hit.label:sources.join(' + '))+' (from Sources, no Tiers on the row)';
}
const arkOnly=sources.length===1&&sources[0]==='AI-Ark';
// Departments: the Hub multi-select (ALL, Executive, Engineering, Technology, Product, Data, R&D,
// Security, Design, Operations, Sales, Marketing, Finance, Human Resources, Customer Success,
// Project Management, Strategy, Legal, Supply Chain, Communications) mapped per provider.
// DiscoLike `department` accepts exactly: Operations, Executive, Technology, Sales - Marketing,
// Finance, Legal, Human Resources, Medical - Science, Customer Service, Research & Development,
// Administration, Public Relations, Investor Relations, Pro Services, Other. Anything else 422s,
// so a pick with no DiscoLike home (Design) is dropped and named in the log, never sent.
const CG_DEP={ 'executive':'Executive', 'engineering':'Technology', 'technology':'Technology', 'product':'Technology', 'data':'Technology', 'r&d':'Research & Development', 'security':'Technology', 'operations':'Operations', 'sales':'Sales - Marketing', 'marketing':'Sales - Marketing', 'finance':'Finance', 'human resources':'Human Resources', 'customer success':'Customer Service', 'project management':'Operations', 'strategy':'Executive', 'legal':'Legal', 'supply chain':'Operations', 'communications':'Public Relations' };
// AI-Ark `contact.departmentAndFunction.any.include` (key and nesting verified in their docs
// 2026-09-02). Values below are verbatim slugs from their taxonomy CSV
// (https://static.ai-ark.com/ark/departments-and-functions.csv, column department_or_function,
// read 2026-09-02): parent departments plus a few named functions. Executive and Strategy have
// no AI-Ark department (executives ride on the seniority filter) and are left unmapped there.
const ARK_DEP={ 'engineering':['engineering_technical'], 'technology':['information_technology'], 'product':['product_management'], 'data':['data_science','data_engineering','business_intelligence'], 'r&d':['research'], 'security':['cybersecurity'], 'design':['design'], 'operations':['operations'], 'sales':['sales'], 'marketing':['marketing'], 'finance':['finance'], 'human resources':['human_resources'], 'customer success':['customer_success_and_support'], 'project management':['program_and_project_management'], 'legal':['legal'], 'supply chain':['supply_chain','procurement','purchasing','transportation_and_logistics'], 'communications':['media_and_communication'] };
const depRaw=arr(f['Departments']).map(s=>String(s).trim()).filter(Boolean);
const wide=!depRaw.length||depRaw.some(d=>d.toUpperCase()==='ALL');
const cgDepartments=[], arkFunctions=[], unmapped=[];
if(!wide){
  for(const d of depRaw){
    const k=d.toLowerCase();
    const cg=CG_DEP[k]; if(cg){ if(cgDepartments.indexOf(cg)<0) cgDepartments.push(cg); } else unmapped.push(d);
    const ark=ARK_DEP[k]; if(ark){ for(const v of [].concat(ark)){ if(arkFunctions.indexOf(v)<0) arkFunctions.push(v); } }
  }
}
// Roles, mapped per provider by the table in this file's header. Values are verbatim from each
// provider's own vocabulary: DiscoLike seniority (executive, vp, director, manager, senior_ic),
// Supersoniq seniority, AI-Ark seniority (founder, owner, partner, c_suite, vp, head, director,
// manager). Nothing outside those lists is ever sent.
const CG_ROLE={ 'founder':'executive', 'owner':'executive', 'partner':'executive', 'board / chair':'executive', 'c-suite':'executive', 'president':'executive', 'executive':'executive', 'vp':'vp', 'evp / svp':'vp', 'head':'director', 'director':'director', 'manager':'manager', 'senior':'senior_ic' };
const SQ_ROLE={ 'founder':['Founder'], 'owner':['Owner'], 'partner':['Partner'], 'board / chair':['Board / Chair'], 'c-suite':['C-Suite'], 'president':['President'], 'executive':['C-Suite'], 'vp':['VP'], 'evp / svp':['EVP / SVP'], 'head':['Head'], 'director':['Director'], 'manager':['Manager','Senior Manager'], 'senior':['Senior'], 'unclassified':['Unclassified'] };
const ARK_ROLE={ 'founder':['founder'], 'owner':['owner'], 'partner':['partner'], 'c-suite':['c_suite'], 'president':['c_suite'], 'executive':['c_suite'], 'vp':['vp'], 'evp / svp':['vp'], 'head':['head'], 'director':['director'], 'manager':['manager'] };
const roleRaw=arr(f['Roles']).map(s=>String(s).trim()).filter(Boolean);
const cgSeniority=[], sqSeniority=[], arkSeniority=[];
const noCg=[], noSq=[], noArk=[];
for(const r of roleRaw){
  const k=r.toLowerCase();
  const cg=CG_ROLE[k]; if(cg){ if(cgSeniority.indexOf(cg)<0) cgSeniority.push(cg); } else noCg.push(r);
  const sq=SQ_ROLE[k]; if(sq){ for(const v of sq){ if(sqSeniority.indexOf(v)<0) sqSeniority.push(v); } } else noSq.push(r);
  const ark=ARK_ROLE[k]; if(ark){ for(const v of ark){ if(arkSeniority.indexOf(v)<0) arkSeniority.push(v); } } else noArk.push(r);
}
const rolesUnmapped=[];
if(noCg.length) rolesUnmapped.push('no ContaGen seniority for '+noCg.join(', '));
if(noSq.length) rolesUnmapped.push('no Supersoniq seniority for '+noSq.join(', '));
if(noArk.length) rolesUnmapped.push('no AI-Ark seniority for '+noArk.join(', '));
return [{ json: {
  refused: '',
  base: base,
  clientRecId: clientRecId,
  table: 'Companies',
  view: view,
  tiers: tiers,
  sources: sources,
  arkOnly: arkOnly,
  departments: depRaw,
  cgDepartments: cgDepartments,
  arkFunctions: arkFunctions,
  departmentsUnmapped: unmapped,
  roles: roleRaw,
  cgSeniority: cgSeniority,
  sqSeniority: sqSeniority,
  arkSeniority: arkSeniority,
  rolesUnmapped: rolesUnmapped,
  maxCompanies: maxCompanies,
  trigger: trigger,
  _launchRecordId: rec.id||'',
  startedAt: startedAt
} }];

// Find Tables: the client base must already carry tables named exactly "Companies" and
// "People" in the register's shape. Nothing here ever creates a table or a field; the
// scaffold is Onboard Client's job (List Building 2.0). DNC is optional and found by name.
const p=$('Launch Params').first().json;
const r=$input.first().json||{};
const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables){ throw new Error('Could not read the table list for base '+p.base+': '+JSON.stringify(body).slice(0,200)+'. Nothing was pulled.'); }
const byName=(n)=>tables.find(x=>String(x.name||'').trim().toLowerCase()===n);
const companies=byName('companies');
if(!companies){ throw new Error('Base '+p.base+' has no Companies table. Scaffold the client base to the List Building 2.0 standard first. Nothing was pulled.'); }
const people=byName('people');
if(!people){ throw new Error('Base '+p.base+' has no People table. Scaffold the client base to the List Building 2.0 standard first. Nothing was pulled.'); }
const cNames=new Set((companies.fields||[]).map(x=>x.name));
for(const need of ['Domain','Company','Employees','Tag','Contacts Pulled At']){ if(!cNames.has(need)){ throw new Error('Companies table '+companies.id+' is missing the core field "'+need+'". Bring it to the register first. Nothing was pulled.'); } }
const pNames=new Set((people.fields||[]).map(x=>x.name));
for(const need of ['Name','Contact Key','Domain','LinkedIn URL','Companies','Contact Source']){ if(!pNames.has(need)){ throw new Error('People table '+people.id+' is missing the core field "'+need+'". Bring it to the register first. Nothing was pulled.'); } }
const dnc=byName('dnc');
return [{ json: Object.assign({}, p, {
  companiesTableId: companies.id, companiesTableName: companies.name, companiesFields: Array.from(cNames),
  peopleTableId: people.id, peopleTableName: people.name, peopleFields: Array.from(pNames),
  dncTableId: dnc?dnc.id:'', dncTableName: dnc?dnc.name:''
}) }];

// Pick Companies: the Companies view rows become the run's company list. Rows without a
// Domain are counted and dropped; duplicate domains collapse to one; Max companies caps
// the list (the spend cap). One item out, always, so the empty-pick gate reaches the close.
// The company's Domain is what the batch builds every Contact Key from; People stores no
// Domain, Company or Tag of its own (lookups through the Companies link), so nothing else
// travels for the write.
const p=$('Launch Params').first().json;
const norm=(d)=>String(d||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
const seen=new Set(); const companies=[];
const stats={ viewRows:0, noDomain:0, duplicate:0, capped:0, picked:0 };
for(const it of $input.all()){
  const j=it.json||{}; if(!j.id) continue; stats.viewRows++;
  const f=j.fields||{};
  const d=norm(f.Domain); if(!d){ stats.noDomain++; continue; }
  if(seen.has(d)){ stats.duplicate++; continue; }
  if(p.maxCompanies&&companies.length>=p.maxCompanies){ stats.capped++; continue; }
  seen.add(d);
  companies.push({ recordId:j.id, domain:d, company:String(f.Company||'').trim(), employees:String(f.Employees==null?'':f.Employees).trim() });
}
stats.picked=companies.length;
return [{ json: { picked: companies.length, domains: companies.map(c=>c.domain), companies: companies, _stats: stats } }];

// People Filters: tier zero reads what the base already holds at these domains, ids only
// (Contact Key, LinkedIn URL, Domain). Domain on People is a lookup through the Companies link
// (People stores none of its own, ruled 2026-09-02); filterByFormula {Domain}='x' matches the
// lookup's text, so these reads keep working unchanged. One OR formula per 100 domains keeps
// every request under Airtable's URL limit; Read People runs once per item and returns all pages.
const d=$input.first().json.domains||[];
const esc=(s)=>String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
const out=[];
for(let i=0;i<d.length;i+=100){
  const chunk=d.slice(i,i+100);
  out.push({ json: { formula: chunk.length===1?("{Domain}='"+esc(chunk[0])+"'"):('OR('+chunk.map(x=>"{Domain}='"+esc(x)+"'").join(',')+')') } });
}
if(!out.length) out.push({ json: { formula: "{Domain}=''" } });
return out;

// Make Batches: held people per company (tier zero: count, Contact Keys, LinkedIn URLs) plus
// 250 companies per batch item, mode "writer" (ContaGen and Supersoniq, the People writer, the
// stamps; AI-Ark is a second pass over the whole run after the last batch, see Ark Pass Item).
// The batch item carries everything the batch needs and the key of the Hub row it will write:
// parentExecId (this execution) and batchNum, dealt once here, 1..N, so "<parentExecId>-<batchNum>"
// is unique by construction. Domain comes back from People as a lookup (an array of one), read
// array-safe.
const p=$('Launch Params').first().json;
const cfg=$('Find Tables').first().json;
const pick=$('Pick Companies').first().json;
const held={};
let heldRows=0;
const domainOf=(f)=>{ const v=f.Domain; return String(Array.isArray(v)?(v[0]||''):(v||'')).trim().toLowerCase(); };
try{
  for(const it of $('Read People').all()){
    const j=it.json||{}; if(!j.id) continue;
    const f=j.fields||{};
    const d=domainOf(f); if(!d) continue;
    heldRows++;
    const h=held[d]||(held[d]={ count:0, keys:[], linkedin:[] });
    h.count++;
    const k=String(f['Contact Key']||'').trim().toLowerCase(); if(k) h.keys.push(k);
    const li=String(f['LinkedIn URL']||'').trim(); if(li) h.linkedin.push(li);
  }
}catch(e){}
const companies=(pick.companies||[]).map(c=>{ const h=held[c.domain]||{ count:0, keys:[], linkedin:[] }; return Object.assign({}, c, { heldCount:h.count, heldKeys:h.keys, heldLinkedin:h.linkedin }); });
const BATCH=250;
const out=[];
for(let i=0;i<companies.length;i+=BATCH){
  out.push({ json: {
    mode: 'writer',
    parentExecId: String($execution.id),
    batchNum: out.length+1, batchCount: Math.ceil(companies.length/BATCH),
    base: p.base, clientRecId: p.clientRecId,
    peopleTableId: cfg.peopleTableId, peopleTableName: cfg.peopleTableName, companiesTableId: cfg.companiesTableId, dncTableId: cfg.dncTableId,
    peopleFields: cfg.peopleFields,
    tiers: p.tiers, sources: p.sources, arkOnly: p.arkOnly, roles: p.roles,
    cgDepartments: p.cgDepartments, arkFunctions: p.arkFunctions,
    cgSeniority: p.cgSeniority, sqSeniority: p.sqSeniority, arkSeniority: p.arkSeniority,
    companies: companies.slice(i,i+BATCH)
  } });
}
if(!out.length) throw new Error('Make Batches received no companies; the empty-pick gate should have caught this.');
out[0].json._stats={ heldRows: heldRows, heldCompanies: companies.filter(c=>c.heldCount>0).length, companiesIn: companies.length, batches: out.length };
return out;

// Pass Result: one writer batch closed (Run Batch, awaited). The sub's last node answers with
// its counters plus the recount's held state (Batch Response); its own Hub row is already written
// when it answers. A crash arrives as an error item: the parent continues past a dead batch and
// logs it, it never retries one (a retry would run the paid tiers twice). stop = a batch whose
// every paid call died: no further batches, straight to the AI-Ark lane over what did close.
// No AI-Ark decision is made here any more (rebuilt 2026-09-02): the whole AI-Ark tier is one
// pass, planned by Ark Lane once the writer lane has drained.
const p=$('Launch Params').first().json;
let batchNum=0; try{ batchNum=Number($('Loop Batches').first().json.batchNum)||0; }catch(e){}
const j=$input.first().json||{};
const out={ mode:'writer', batchNum:batchNum, key:String(batchNum), status:'closed', written:0, allFailed:false, stop:false, reason:'' };
if(j.error!==undefined&&j.error!==null&&j.error!==''){
  out.status='crashed';
  out.reason=String((typeof j.error==='object'?(j.error.message||j.error.description||JSON.stringify(j.error)):j.error)||'crashed').slice(0,200);
  return [{ json: out }];
}
if(Number(j.batchNum)>0){ out.batchNum=Number(j.batchNum); out.key=String(out.batchNum); }
out.written=Number(j.written)||0;
out.allFailed=!!j.allFailed;
if(out.allFailed){
  out.status='allFailed';
  out.reason=String((Array.isArray(j.failReasons)&&j.failReasons[0])||'every paid call failed after retry').slice(0,200);
  out.stop=true;
}
return [{ json: out }];

// Find Waterfall View: after every lane group closes, read the base meta again. The email door is
// fired only when the People table carries a view named exactly "Not Waterfalled" (the register's
// view: relevance = 1 and Status empty); otherwise the hand-over is a skip in the log. Nothing else
// (ruled 2026-09-02). No Fire Waterfall field exists on the launch row.
const cfg=$('Find Tables').first().json;
const r=$input.first().json||{};
const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:[];
const t=tables.find(x=>x.id===cfg.peopleTableId)||null;
const VIEW='Not Waterfalled';
const v=t?((t.views||[]).find(x=>String(x.name||'').trim()===VIEW)):null;
return [{ json: { hasView: !!v, viewName: VIEW, viewId: v?v.id:'', metaOk: tables.length>0 } }];

// Handoff Tick: closes one hand-off (after every writer batch, and once more after the AI-Ark
// lane's row landed) with the live Running row. This hand-off's outcome is read from the node's own
// input (Fire Waterfall's answer, or the view check when People has no "Not Waterfalled" view:
// Fire Waterfall did not run this time, and reading it by name would return an older answer).
// The run so far is read from every Pass Result run and every Fire Waterfall run (run by run,
// until a run index does not exist), and from Ark Lane and Ark Rows Check once they have run
// (during the writer loop neither has, and both reads fall through to "not fired yet").
// No Tally here, no read-add-write (ruled 2026-09-02): the pass rows carry the counters, the close
// reads them by prefix. The item out is the row, nothing else, so Stamp Progress can auto-map it;
// the gates after it read Pass Result and Ark Rows Check.
const p=$('Launch Params').first().json;
const cfg=$('Find Tables').first().json;
let batchCount=0, total=0; try{ const s=$('Make Batches').first().json._stats||{}; total=Number(s.companiesIn)||0; batchCount=Number(s.batches)||0; }catch(e){}
const runs=(name)=>{ const out=[]; for(let i=0;i<10000;i++){ let it=null; try{ it=$(name).all(0,i); }catch(e){ break; } if(!it||!it.length) break; out.push(it); } return out; };
const batches=runs('Pass Result').map(r=>r[0].json||{});
const closed=batches.filter(x=>x.status==='closed').length;
const written=batches.reduce((a,x)=>a+(Number(x.written)||0),0);
let lane=null; try{ lane=$('Ark Lane').first().json||null; }catch(e){}
let ark=null; try{ ark=$('Ark Rows Check').first().json||null; }catch(e){}
